#include <cstdio>
#include <cstring>

char s[100005];
char stk[100005];

int main() {
    if (!fgets(s, sizeof(s), stdin)) { printf("\n"); return 0; }
    int len = (int)strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r')) s[--len] = 0;

    int top = 0;
    for (int i = 0; i < len; ++i) {
        if (top > 0 && stk[top - 1] == s[i]) --top;   // 消除一对
        else stk[top++] = s[i];
    }
    stk[top] = 0;
    printf("%s\n", stk);
    return 0;
}
